            px0: m[0], py0: m[1], xr: xr, yr: yr,
            stretch: !!(event.altKey || event.shiftKey),
            gx: xr[0] + _clampF(m[0] / W) * (xr[1] - xr[0]),
            gy: yr[1] - _clampF(m[1] / H) * (yr[1] - yr[0]),
            pointerId: event.pointerId,
